DROP TRIGGER IF EXISTS notify_customer_tracking ON public.shipment_events;
CREATE OR REPLACE FUNCTION public.manage_customer_notification(p_id uuid DEFAULT NULL,p_action text DEFAULT 'read') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_customer() THEN RAISE EXCEPTION 'Active customer required'; END IF; IF p_action='read' THEN UPDATE public.customer_notifications SET read_at=coalesce(read_at,now()) WHERE user_id=auth.uid() AND (p_id IS NULL OR id=p_id); ELSIF p_action='delete' AND p_id IS NOT NULL THEN DELETE FROM public.customer_notifications WHERE user_id=auth.uid() AND id=p_id AND read_at IS NOT NULL; ELSE RAISE EXCEPTION 'Invalid notification action'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.respect_customer_notification_preferences() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND notification_preferences->>NEW.category='false') THEN RETURN NULL; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS customer_notification_preferences ON public.customer_notifications;
CREATE TRIGGER customer_notification_preferences BEFORE INSERT ON public.customer_notifications FOR EACH ROW EXECUTE FUNCTION public.respect_customer_notification_preferences();